<?php require_once '../config/auth.php';$page_title='Leads';$base='../';$rows=$pdo->query("SELECT l.*,u.name owner FROM leads l LEFT JOIN users u ON u.id=l.owner_id ORDER BY l.created_at DESC")->fetchAll();include '../partials/header.php';?><div class="d-flex justify-content-between mb-3"><div><h4>Leads</h4><p class="text-muted">Track prospects to conversion.</p></div><a class="btn btn-primary" href="form.php">+ Add lead</a></div><div class="cardx table-responsive"><table class="table"><thead><tr><th>Lead</th><th>Company</th><th>Source</th><th>Status</th><th>Value</th><th>Owner</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['company'])?></td><td><?=e($r['source'])?></td><td><span class="status"><?=e(ucfirst($r['status']))?></span></td><td>$<?=number_format($r['estimated_value'],2)?></td><td><?=e($r['owner']??'Unassigned')?></td><td><a class="btn btn-sm btn-light" href="form.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div><?php include '../partials/footer.php';?>